export const SKILLS = {
  checkmates:{name:'Checkmates',short:'Close every escape',icon:'♚',description:'Put the king in check with no safe escape.',tip:'After a check, look for every escape, capture, and block.'},
  forks:{name:'Forks',short:'Find two targets',icon:'♞',description:'Use one piece to attack two targets at once.',tip:'Look for a move that attacks the king and another valuable piece.'},
  pins:{name:'Pins',short:'Find the trapped defender',icon:'♝',description:'Take advantage of a piece that cannot safely move.',tip:'Trace a straight line through a piece to the king or queen behind it.'},
  calculation:{name:'Calculation',short:'Think one reply ahead',icon:'♜',description:'Picture your move, their reply, and your next move.',tip:'Compare checks, captures, and threats before choosing a move.'}
};
export const LESSONS={
  checkmates:[['The king has no way out','Checkmate needs two things: the king is attacked, and every possible answer fails. Before moving, check whether the king can move, capture the attacker, or block the check.'],['Count the escape squares','Look at each square next to the enemy king. Your pieces, their pieces, and the edge of the board may already cover most of them. Find a check that closes the rest.'],['Bring a helper','A queen beside the king often needs protection. Find which friendly piece protects your checking piece before you bring it close.'],['Look along the back rank','A king behind its own pawns can be trapped. A rook or queen check along that rank can be very strong. Always check whether the attack can be blocked.'],['Force the next check','For a mate in several moves, start with forcing checks. Picture the king’s reply, then look for the next check. Do not stop calculating after the first move.'],['Avoid a quiet escape','A tempting capture can give the king time to escape. Compare it with a forcing check and count the escape squares again.']],
  forks:[['One move, two threats','A fork attacks two targets at once. A check is especially useful: the opponent must protect the king before saving the other piece.'],['The knight’s double attack','A knight jumps two squares in one direction and one sideways. Look at all eight possible jumps and ask which one attacks two valuable targets.'],['Forks are not just for knights','Queens, rooks, bishops, pawns, and kings can also attack two pieces at once. Look for checks that attack another piece along a second line.'],['Make the fork possible','Sometimes you need a capture or check first. Picture the opponent’s forced reply, then look for the square where the fork becomes possible.'],['Check the fork square','Before playing your double attack, ask whether the forking piece can simply be captured. Check every opponent piece that attacks its destination.'],['Collect the second target','Finding the fork is only half the job. Calculate the opponent’s reply and make sure you can still capture the second target afterwards.']],
  pins:[['A defender that cannot leave','A piece in front of its king cannot move if doing so would expose check. This is a pin. Look for a rook, bishop, or queen lined up with the king.'],['Attack the pinned piece','Once a defender is pinned, bring another piece to attack it. Before capturing, check whether the king or another piece can safely recapture.'],['Look beyond the first piece','Follow every rook, bishop, and queen line past the first enemy piece. A king or queen behind it may turn that piece into a tactical target.'],['Pins can protect a capture','A defender may appear to guard a square, but moving could expose its king. Check whether it can legally recapture before rejecting your move.'],['Create the line first','A forcing capture may open a file or diagonal for your pin. Calculate the reply and inspect the newly opened line.'],['King pins and queen pins','A pin to the king is a legal restriction. A pin to the queen is a choice: the piece can move, but may lose the queen. Do not assume both work the same way.']],
  calculation:[['My move, their reply, my move','Choose a candidate move. Picture the opponent’s strongest reply. Then decide what you would do next. Keep the pieces in their new squares in your mind.'],['Start with forcing moves','Checks and captures narrow the opponent’s choices. Look at them first, but still check every legal answer before deciding.'],['Count the exchanges','When pieces trade, count what each side gives up and gets back. Pawns are about 1 point, knights and bishops 3, rooks 5, and queens 9.'],['Find the opponent’s best reply','A plan is only strong if it survives a good reply. Look for their checks, captures, and threats instead of imagining a convenient response.'],['Look one move further','An attractive capture may lose a piece on the next turn. Before moving, extend the line by one more reply and check what changed.'],['Compare two candidates','Calculate two promising moves separately. Choose the one that gives the better result against the opponent’s strongest answer.']]
};
export const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
export function startingTarget(rating){return rating==null?650:clamp(Math.round((Number(rating)-100)/25)*25,450,2300)}
export function newCoach(rating){return Object.fromEntries(Object.keys(SKILLS).map(s=>[s,{target:startingTarget(rating),fast:0,struggles:0,solved:0,total:0,reason:rating==null?'Starting gently while we find your level.':'Starting near your rating; your answers will guide the next steps.'}]))}
export function adapt(previous,result){const c={...previous,total:previous.total+1,solved:previous.solved+(result.clean?1:0)};const fastLimit=Math.max(25,result.playerMoves*20);if(result.clean){c.struggles=0;if(result.seconds<=fastLimit){c.fast++;const rise=c.fast>=3?125:c.fast>=2?100:25;c.target=clamp(c.target+rise,400,2500);c.reason=c.fast>=2?'You solved several quickly and without help. Let’s try a harder puzzle.':'A clean, quick solve. A small step up while we confirm your level.';}else{c.fast=0;const rise=result.seconds<=fastLimit*2?25:0;c.target=clamp(c.target+rise,400,2500);c.reason=rise?'Accurate work. A small step up; there is no need to rush.':'You solved it with careful thought. Let’s stay at this level.';}}else{c.fast=0;c.struggles++;if(c.struggles>=2){c.target=clamp(c.target-75,400,2500);c.struggles=0;c.reason='A couple of tricky puzzles. A small step down to rebuild confidence.';}else c.reason='A mistake or some help this time. We’ll hold the difficulty steady.';}return c;}
export function recommendSkill(state){const keys=Object.keys(SKILLS),sessions=state.sessions.filter(s=>s.version===2);for(const k of keys)if(!sessions.some(s=>s.skill===k))return k;let recent=sessions.slice(-8),last=sessions.at(-1)?.skill;return keys.filter(k=>k!==last).sort((a,b)=>{let aa=recent.filter(s=>s.skill===a).flatMap(s=>s.results),bb=recent.filter(s=>s.skill===b).flatMap(s=>s.results);return (aa.length?aa.filter(x=>x.clean).length/aa.length:-1)-(bb.length?bb.filter(x=>x.clean).length/bb.length:-1)})[0]||keys[0];}
export function pickPuzzle(bank,skill,target,seen,seenPositions){const ids=new Set(seen),positions=new Set(seenPositions);return bank.filter(p=>p.skill===skill&&!ids.has(p.id)&&!positions.has(positionKey(p.fen))).sort((a,b)=>Math.abs(a.rating-target)-Math.abs(b.rating-target)||a.id.localeCompare(b.id))[0]||null;}
export function positionKey(fen){return fen.split(' ').slice(0,2).join(' ')}
export function lessonFor(state,skill,puzzle){const used=new Set(state.sessions.filter(s=>s.version===2).map(s=>s.lessonId));for(let i=0;i<LESSONS[skill].length;i++)if(!used.has(skill+'-'+i))return {id:skill+'-'+i,title:LESSONS[skill][i][0],body:LESSONS[skill][i][1]};return {id:'position-'+puzzle.id,title:'Find the '+({forks:'double attack',pins:'pinned defender',checkmates:'mating pattern',calculation:'forcing sequence'}[skill]),body:SKILLS[skill].description+' This is a fresh position from a real game. '+SKILLS[skill].tip};}
export function weekKey(now=new Date()){const d=new Date(now);d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return localDate(d)}
export function localDate(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
export function normalize(raw){const base={schema:2,sessions:[],ratings:[],checks:{},seen:[],seenPositions:[],profile:null,coach:null,active:null};if(!raw)return base;const s={...base,...raw,schema:2};s.sessions=Array.isArray(s.sessions)?s.sessions:[];s.ratings=Array.isArray(s.ratings)?s.ratings:[];if(!Array.isArray(s.seen))s.seen=[];if(!Array.isArray(s.seenPositions))s.seenPositions=[];return s;}
export function validBackup(x,bankIds){
  const dateOK=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v);
  const finite=(v,min=0,max=Number.MAX_SAFE_INTEGER)=>Number.isFinite(v)&&v>=min&&v<=max;
  const resultOK=r=>r&&bankIds.has(r.id)&&finite(r.seconds)&&typeof r.clean==='boolean'&&Array.isArray(r.mistakes)&&finite(r.hints,0,2)&&finite(r.rating,100,3500)&&finite(r.targetAfter,400,2500);
  if(!x||!Array.isArray(x.sessions)||!Array.isArray(x.ratings)||!x.checks||typeof x.checks!=='object'||Array.isArray(x.checks))return false;
  for(const r of x.ratings)if(!finite(r.value,100,3500)||!dateOK(r.date)||typeof r.source!=='string')return false;
  for(const s of x.sessions){
    if(!dateOK(s.date))return false;
    if(s.version===2){if(!SKILLS[s.skill]||!finite(s.seconds)||!Array.isArray(s.results)||s.results.some(r=>!resultOK(r))||typeof s.lessonTitle!=='string'||typeof s.tip!=='string')return false;}
    else if(!/^([0-3])-([0-3])$/.test(s.lesson)||!Array.isArray(s.answers)||!Array.isArray(s.outcomes)||!finite(Number(s.minutes),1,180))return false;
  }
  if(x.schema===2){
    if(!Array.isArray(x.seen)||!x.seen.every(s=>typeof s==='string')||!Array.isArray(x.seenPositions)||!x.seenPositions.every(s=>typeof s==='string'))return false;
    if(x.profile&&(!finite(x.profile.goal,100,3500)||x.profile.currentRating!=null&&!finite(x.profile.currentRating,100,3500)))return false;
    if(x.coach&&Object.keys(SKILLS).some(k=>{const c=x.coach[k];return !c||!finite(c.target,400,2500)||!finite(c.total)||!finite(c.solved)||!finite(c.fast)||!finite(c.struggles)}))return false;
    if(x.active){const a=x.active;if(!SKILLS[a.skill]||!dateOK(a.date)||!finite(a.seconds)||!Array.isArray(a.results)||a.results.some(r=>!resultOK(r))||!['puzzles','notes'].includes(a.stage)||typeof a.lessonTitle!=='string'||typeof a.lessonBody!=='string'||typeof a.tip!=='string')return false;
      const p=a.puzzle;if(!p||!bankIds.has(p.id)||!finite(p.cursor,0,20)||!Number.isInteger(p.cursor)||!finite(p.seconds)||!Array.isArray(p.mistakes)||!Array.isArray(p.moves)||!finite(p.hints,0,2)||typeof p.done!=='boolean')return false;
    }
  }
  if(x.draft&&(!/^([0-3])-([0-3])$/.test(x.draft.lesson)||!Array.isArray(x.draft.answers)||!Array.isArray(x.draft.outcomes)))return false;
  return true;
}
